code.DataFrame:
$events = DataFrame::fromCsv('events.csv');
$dims = DataFrame::fromCsv('dims.csv');

$rows = $events
    ->groupBy(['key'])
    ->summarise(['n' => n(), 'mean_x' => mean(col('x'), na_rm: true), 'sum_x' => sum(col('x'), na_rm: true)])
    ->collect()->nrow();

code.SqlTable:
$pdo = new PDO('sqlite:bench.sqlite');
$events = SqlTable::table($pdo, 'events');
$dims = SqlTable::table($pdo, 'dims');

$rows = $events
    ->groupBy(['key'])
    ->summarise(['n' => n(), 'mean_x' => mean(col('x'), na_rm: true), 'sum_x' => sum(col('x'), na_rm: true)])
    ->collect()->nrow();

